public class BankAccount {
    private double balance; // Encapsulated internal state

    // Public API for controlled mutation
    public void deposit(double amount) {
        if (amount > 0) this.balance += amount;
    }

    // Package-private helper for internal auditing
    void logTransaction(String details) {
        System.out.println("Audit: " + details);
    }
}
